import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.CDU0sSpB.js";const h=JSON.parse('{"title":"6.4 Long-running operation and v1.0 acceptance","description":"Run stably for the long term, then release v1.0 after full acceptance.","frontmatter":{"title":"6.4 Long-running operation and v1.0 acceptance","description":"Run stably for the long term, then release v1.0 after full acceptance.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-6/6-4.md","filePath":"en/delivery/stage-6/6-4.md","lastUpdated":1793859143000}'),r={name:"en/delivery/stage-6/6-4.md"};function i(l,e,s,c,d,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="_6-4-long-running-operation-and-v1-0-acceptance" tabindex="-1">6.4 Long-running operation and v1.0 acceptance <a class="header-anchor" href="#_6-4-long-running-operation-and-v1-0-acceptance" aria-label="Permalink to &quot;6.4 Long-running operation and v1.0 acceptance&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Let Hearth run quietly for the long term and release v1.0 after full capability acceptance. Long-running operation is not just avoiding crashes; resources must stay bounded, state must not drift, and permission must not expand.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Add health checks, resource limits, logs, and alerts so the user knows when something is wrong.</li><li>Regularly clean temporary files, expired tasks, and unneeded caches so resources do not grow forever.</li><li>Run a continuous test for at least several weeks and check memory, task state, sync, and permission stability.</li><li>Complete overall acceptance across the main task types, including install, upgrade, backup, restore, revocation, and a privacy explanation.</li><li>Check that every high-risk action still requires approval and every external action has a receipt.</li><li>Release v1.0 only when the user can install, use, migrate, and leave independently.</li></ol>',5)])])}const g=a(r,[["render",i]]);export{h as __pageData,g as default};
